// System message payloads which contain neither pointers nor native handles.
// No 'all small integers are safe' heuristic is used for unknown system IDs.
bool scalar_message(UINT m){
    if(m>=WM_USER)return true;
    if((m>=WM_KEYFIRST && m<=WM_KEYLAST) || (m>=WM_MOUSEFIRST && m<=WM_MOUSELAST) || (m>=WM_NCMOUSEMOVE && m<=WM_NCXBUTTONDBLCLK))return true;
    switch(m){case WM_QUERYNEWPALETTE:case WM_NULL:case WM_DESTROY:case WM_MOVE:case WM_SIZE:case WM_ENABLE:case WM_SETREDRAW:case WM_PAINT:case WM_CLOSE:case WM_QUERYENDSESSION:case WM_QUERYOPEN:case WM_ENDSESSION:case WM_SHOWWINDOW:case WM_CANCELMODE:case WM_CHILDACTIVATE:case WM_GETTEXTLENGTH:case WM_TIMECHANGE:case WM_SYSCOLORCHANGE:case WM_NCDESTROY:case WM_NCHITTEST:case WM_SYNCPAINT:case WM_SYSCOMMAND:case WM_DISPLAYCHANGE:case WM_ENTERMENULOOP:case WM_EXITMENULOOP:case WM_ENTERSIZEMOVE:case WM_EXITSIZEMOVE:case WM_MOUSEHOVER:case WM_MOUSELEAVE:case WM_NCMOUSEHOVER:case WM_NCMOUSELEAVE:case WM_IME_SETCONTEXT:case WM_IME_NOTIFY:case WM_IME_STARTCOMPOSITION:case WM_IME_ENDCOMPOSITION:case WM_IME_COMPOSITION:case WM_IME_CHAR:case WM_IME_KEYDOWN:case WM_IME_KEYUP:case WM_TIMER:case WM_QUIT:case WM_DWMCOMPOSITIONCHANGED:case WM_DWMNCRENDERINGCHANGED:case WM_DWMCOLORIZATIONCOLORCHANGED:case WM_DWMWINDOWMAXIMIZEDCHANGE:return true;default:return false;}
}
